(function(){
  var WALL_IMG = 'data:image/jpeg;base64,';
  var IMG = {
  dand_1_seedhead:'data:image/jpeg;base64,',
  dand_2_singleseed:'data:image/jpeg;base64,',
  dand_3_sprout:'data:image/jpeg;base64,',
  dand_4_seedling:'data:image/jpeg;base64,',
  dand_5_rosette:'data:image/jpeg;base64,',
  dand_6_bud:'data:image/jpeg;base64,',
  dand_7_flower:'data:image/jpeg;base64,',
  dand_8_bloom:'data:image/jpeg;base64,',
  frog_1_eggs:'data:image/jpeg;base64,',
  frog_2_tadpole:'data:image/jpeg;base64,',
  frog_3_tadpole_legs:'data:image/jpeg;base64,',
  frog_4_froglet_tail:'data:image/jpeg;base64,',
  frog_5_froglet:'data:image/jpeg;base64,',
  frog_6_youngfrog:'data:image/jpeg;base64,',
  frog_7_subadult:'data:image/jpeg;base64,',
  frog_8_adult:'data:image/jpeg;base64,'
};

  var STYLE_ID = 'cg-style-1E';

  var LEVELS = [
    { key:'butterfly', name:'Butterfly Life Cycle', stages:[
        {label:'Egg', emoji:'\u{1F95A}'},
        {label:'Caterpillar', emoji:'\u{1F41B}'},
        {label:'Chrysalis', shape:'cg-chrysalis'},
        {label:'Butterfly', emoji:'\u{1F98B}'}
      ]},
    { key:'dandelion', name:'Dandelion Life Cycle', stages:[
        {label:'Seed head', img:IMG.dand_1_seedhead},
        {label:'Drifting seed', img:IMG.dand_2_singleseed},
        {label:'Sprouting', img:IMG.dand_3_sprout},
        {label:'Seedling', img:IMG.dand_4_seedling},
        {label:'Rosette', img:IMG.dand_5_rosette},
        {label:'Bud', img:IMG.dand_6_bud},
        {label:'Flower', img:IMG.dand_7_flower},
        {label:'Full bloom', img:IMG.dand_8_bloom}
      ]},
    { key:'frog', name:'Frog Life Cycle', stages:[
        {label:'Eggs', img:IMG.frog_1_eggs},
        {label:'Tadpole', img:IMG.frog_2_tadpole},
        {label:'Growing legs', img:IMG.frog_3_tadpole_legs},
        {label:'Froglet + tail', img:IMG.frog_4_froglet_tail},
        {label:'Froglet', img:IMG.frog_5_froglet},
        {label:'Young frog', img:IMG.frog_6_youngfrog},
        {label:'Sub-adult', img:IMG.frog_7_subadult},
        {label:'Adult frog', img:IMG.frog_8_adult}
      ]}
  ];

  var TOTAL_HOLDS = LEVELS.reduce(function(sum,l){ return sum + l.stages.length; }, 0);
  var HOLD_COLORS = ['#e94f37','#3fa7d6','#f6c445','#5cb85c','#a55eea','#ff8fa3','#4fd1c5','#f4a261'];

  function buildHolds(n){
    var holds = [];
    for (var i=0;i<n;i++){
      var t = n===1 ? 0 : i/(n-1);
      var y = 92 - t*(92-8);
      var x = 69 + 20*Math.sin(i*1.4);
      holds.push({x:x, y:y});
    }
    return holds;
  }
  var HOLDS = buildHolds(TOTAL_HOLDS);

  function ensureStyle(){
    if (document.getElementById(STYLE_ID)) return;
    var css = ''
      + '.cg-wrap{display:flex;flex-direction:column;gap:14px;}'
      + '.cg-stage{position:relative;width:100%;border-radius:14px;overflow:hidden;box-shadow:0 4px 14px rgba(0,0,0,.3);line-height:0;}'
      + '.cg-stage img.cg-bg{display:block;width:100%;height:auto;}'
      + '.cg-hold{position:absolute;width:5.2%;aspect-ratio:1/1;border-radius:50% 50% 50% 20%;transform:translate(-50%,-50%) rotate(-15deg);box-shadow:0 3px 6px rgba(0,0,0,.35), inset 0 -3px 5px rgba(0,0,0,.25);border:2px solid rgba(255,255,255,.65);}'
      + '.cg-hold.cg-done{filter:brightness(1.15);}'
      + '.cg-hold.cg-next{animation:cg-pulse 1.1s infinite;}'
      + '@keyframes cg-pulse{0%,100%{box-shadow:0 3px 6px rgba(0,0,0,.35),0 0 0 0 rgba(255,255,255,.55);}50%{box-shadow:0 3px 6px rgba(0,0,0,.35),0 0 0 7px rgba(255,255,255,0);}}'
      + '.cg-rope{position:absolute;inset:0;stroke:rgba(255,255,255,.55);stroke-width:.35%;stroke-dasharray:1 1.3;fill:none;}'
      + '.cg-clover{position:absolute;width:9%;transform:translate(-50%,-95%);filter:drop-shadow(0 3px 3px rgba(0,0,0,.4));z-index:5;transition:left .5s ease, top .5s ease;}'
      + '.cg-clover img{display:block;width:100%;}'
      + '.cg-flag{position:absolute;font-size:6vw;transform:translate(-50%,-100%);}'
      + '.cg-overlay{position:absolute;left:1.5%;top:3%;width:34%;background:rgba(8,31,44,.82);border:2px solid rgba(98,203,201,.5);border-radius:12px;padding:10px 12px;color:#fff;box-sizing:border-box;}'
      + '.cg-overlay .h3{margin:0 0 4px;font-size:15px;}'
      + '.cg-overlay .sub{font-size:11.5px;opacity:.85;margin:0 0 8px;line-height:1.35;}'
      + '.cg-tiles{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;}'
      + '.cg-tile{width:44%;padding:6px 4px;border-radius:10px;border:none;cursor:pointer;background:#62CBC9;color:#081F2C;font-weight:800;font-size:11px;display:flex;flex-direction:column;align-items:center;gap:4px;transition:transform .1s ease, opacity .3s ease;}'
      + '.cg-tile:active{transform:scale(.94);}'
      + '.cg-tile.cg-wrong{animation:cg-shake .3s;}'
      + '.cg-tile.cg-tapdone{opacity:.3;pointer-events:none;background:#3a4c52;color:#bcd;}'
      + '@keyframes cg-shake{25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}'
      + '.cg-tile .cg-ic{font-size:22px;line-height:1;}'
      + '.cg-tile img{width:100%;max-height:44px;object-fit:contain;border-radius:6px;background:#fff;}'
      + '.cg-fb{min-height:16px;font-weight:700;font-size:12px;margin-top:6px;}'
      + '.cg-hud{display:flex;justify-content:space-between;font-size:11px;opacity:.85;margin-top:8px;font-weight:700;}'
      + '.cg-chrysalis{width:20px;height:32px;border-radius:50% 50% 45% 45%/60% 60% 40% 40%;background:#6b8f3a;}'
      + '@media (max-width:640px){.cg-overlay{width:44%;padding:8px;}.cg-overlay .h3{font-size:12.5px;}.cg-overlay .sub{font-size:9.5px;}.cg-tile{font-size:9px;}.cg-tile img{max-height:32px;}}'
      ;
    var tag = document.createElement('style');
    tag.id = STYLE_ID;
    tag.textContent = css;
    document.head.appendChild(tag);
  }

  function shuffle(arr){
    var a = arr.slice();
    for (var i=a.length-1;i>0;i--){
      var j = Math.floor(Math.random()*(i+1));
      var tmp=a[i]; a[i]=a[j]; a[j]=tmp;
    }
    return a;
  }

  function start(host, ctx){
    ensureStyle();

    host.innerHTML =
      '<div class="cg-wrap">' +
        '<div class="cg-stage" id="cgStage">' +
          '<img class="cg-bg" src="'+WALL_IMG+'" alt="climbing wall">' +
          '<svg class="cg-rope" id="cgRope" viewBox="0 0 100 100" preserveAspectRatio="none"></svg>' +
          '<div class="cg-overlay" id="cgOverlay">' +
            '<div class="h3" id="cgLevelName"></div>' +
            '<div class="sub" id="cgPrompt"></div>' +
            '<div class="cg-tiles" id="cgTiles"></div>' +
            '<div class="cg-fb" id="cgFb"></div>' +
            '<div class="cg-hud"><span>\u{1FA99} <span id="cgCoins">0</span></span><span>Hold <span id="cgHoldNum">1</span>/'+TOTAL_HOLDS+'</span></div>' +
          '</div>' +
        '</div>' +
        '<div class="row center mt">' +
          '<button class="btn ghost sm" id="cgMapBtn">\u2190 Map</button>' +
        '</div>' +
      '</div>';

    var stage = host.querySelector('#cgStage');
    var ropeSvg = host.querySelector('#cgRope');

    HOLDS.forEach(function(h,i){
      var d = document.createElement('div');
      d.className = 'cg-hold' + (i===0 ? ' cg-next' : '');
      d.style.left = h.x+'%'; d.style.top = h.y+'%';
      d.style.background = HOLD_COLORS[i % HOLD_COLORS.length];
      d.id = 'cgHold'+i;
      stage.appendChild(d);
    });

    var ropePath = '';
    HOLDS.forEach(function(h,i){ ropePath += (i===0?'M':'L') + h.x + ' ' + h.y + ' '; });
    var ropeEl = document.createElementNS('http://www.w3.org/2000/svg','path');
    ropeEl.setAttribute('d', ropePath);
    ropeEl.setAttribute('class','cg-rope');
    ropeSvg.appendChild(ropeEl);

    var flag = document.createElement('div');
    flag.className = 'cg-flag';
    flag.textContent = '\u{1F6A9}';
    flag.style.left = HOLDS[HOLDS.length-1].x + '%';
    flag.style.top = (HOLDS[HOLDS.length-1].y - 3) + '%';
    stage.appendChild(flag);

    var clover = document.createElement('div');
    clover.className = 'cg-clover';
    clover.innerHTML = '<img id="cgCloverImg" src="'+ctx.clover.head+'" alt="Clover">';
    clover.style.left = HOLDS[0].x + '%';
    clover.style.top = (HOLDS[0].y + 3) + '%';
    stage.appendChild(clover);

    var globalIdx = 0;
    var levelI = 0;
    var expected = 0;
    var order = [];
    var coins = 0;
    var wrongTaps = 0;

    var elLevelName = host.querySelector('#cgLevelName');
    var elPrompt = host.querySelector('#cgPrompt');
    var elTiles = host.querySelector('#cgTiles');
    var elFb = host.querySelector('#cgFb');
    var elCoins = host.querySelector('#cgCoins');
    var elHoldNum = host.querySelector('#cgHoldNum');
    var cloverImg = host.querySelector('#cgCloverImg');

    function renderTiles(){
      var lvl = LEVELS[levelI];
      elLevelName.textContent = lvl.name;
      elPrompt.textContent = expected===0
        ? 'Help Clover! Tap the stages in order, starting with the first one.'
        : 'Great — tap the next stage.';
      elTiles.innerHTML = '';
      order.forEach(function(si){
        var s = lvl.stages[si];
        var btn = document.createElement('button');
        btn.className = 'cg-tile' + (si < expected ? ' cg-tapdone' : '');
        var icHtml;
        if (s.img){ icHtml = '<img src="'+s.img+'" alt="'+s.label+'">'; }
        else if (s.shape){ icHtml = '<span class="cg-ic"><span class="'+s.shape+'"></span></span>'; }
        else { icHtml = '<span class="cg-ic">'+s.emoji+'</span>'; }
        btn.innerHTML = icHtml + '<span>'+s.label+'</span>';
        if (si >= expected){
          btn.addEventListener('pointerup', function(){ tapStage(si, btn); });
        }
        elTiles.appendChild(btn);
      });
    }

    function tapStage(si, btn){
      if (si === expected){
        elFb.textContent = 'Yes! Clover climbs up! \u{1F389}';
        elFb.className = 'cg-fb';
        coins += 1;
        elCoins.textContent = coins;
        ctx.award({coins:1});

        var holdEl = host.querySelector('#cgHold'+globalIdx);
        if (holdEl){ holdEl.classList.remove('cg-next'); holdEl.classList.add('cg-done'); }
        globalIdx++;

        if (globalIdx < HOLDS.length){
          clover.style.left = HOLDS[globalIdx].x + '%';
          clover.style.top = (HOLDS[globalIdx].y + 3) + '%';
          var nextHold = host.querySelector('#cgHold'+globalIdx);
          if (nextHold) nextHold.classList.add('cg-next');
          elHoldNum.textContent = globalIdx+1;
        }

        expected++;
        if (expected >= LEVELS[levelI].stages.length){
          if (levelI < LEVELS.length-1){
            var doneName = LEVELS[levelI].name;
            ctx.award({coins:5});
            coins += 5;
            elCoins.textContent = coins;
            elFb.textContent = doneName + ' complete! On to the next one.';
            if (ctx.confetti) ctx.confetti();
            if (ctx.toast) ctx.toast(doneName + ' complete!');
            levelI++;
            expected = 0;
            order = shuffle(LEVELS[levelI].stages.map(function(_,i){return i;}));
            setTimeout(renderTiles, 1200);
            return;
          } else {
            finishClimb();
            return;
          }
        }
        renderTiles();
      } else {
        wrongTaps++;
        elFb.textContent = 'Not the next stage yet — look for what comes ' + (expected===0 ? 'first.' : 'next.');
        elFb.className = 'cg-fb';
        btn.classList.add('cg-wrong');
        setTimeout(function(){ btn.classList.remove('cg-wrong'); }, 300);
      }
    }

    function finishClimb(){
      clover.style.left = HOLDS[globalIdx-1].x + '%';
      clover.style.top = (HOLDS[globalIdx-1].y - 2) + '%';
      cloverImg.src = ctx.clover.cele;
      elLevelName.textContent = 'Clover reached the top! \u2B50';
      elPrompt.textContent = 'You helped Clover climb all three life cycles!';
      elTiles.innerHTML = '';
      elFb.textContent = 'Great job helping Clover climb the wall!';
      if (ctx.confetti) ctx.confetti();

      var alreadyEarned = !!ctx.state.climbinggymStarEarned;
      var doingWell = wrongTaps <= 8;
      if (!alreadyEarned && doingWell){
        ctx.state.climbinggymStarEarned = true;
        ctx.award({coins:5, star:true});
        coins += 5;
        elCoins.textContent = coins;
      } else if (!alreadyEarned){
        ctx.award({coins:5});
        coins += 5;
        elCoins.textContent = coins;
        if (ctx.toast) ctx.toast('So close! Try again for your star.');
      } else {
        ctx.award({coins:5});
        coins += 5;
        elCoins.textContent = coins;
      }
    }

    order = shuffle(LEVELS[0].stages.map(function(_,i){return i;}));
    renderTiles();

    host.querySelector('#cgMapBtn').addEventListener('pointerup', function(){ ctx.close(); });
  }

  window.Stops.register('1E', { name:'ROKC Climbing Gym', start:start });
})();
